-- =====================================================================
-- 00. SUPABASE AUTH USERS & UNIVERSAL PASSWORD SEED ('1234567')
-- =====================================================================
-- Seeds 2,735 accounts into auth.users and auth.identities (112 Principals,
-- 493 Teachers, 2,130 Students) and updates ALL existing users to: 1234567
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. Set password '1234567' for ALL currently existing users in auth.users
UPDATE auth.users
SET 
  encrypted_password = extensions.crypt('1234567', extensions.gen_salt('bf')),
  email_confirmed_at = COALESCE(email_confirmed_at, now()),
  updated_at = now();

-- 2. Insert dummy accounts into auth.users
INSERT INTO auth.users (
